// Route-handler coverage for the personal calendar feed: which dates a
// subscriber's calendar app is handed, and how an invite-only one reads there.
//
// Invite only is a badge and hides nothing (docs/calendar.md). Until 2026-10-30
// this route dropped every invite-only date, marked itself or generated by an
// invite-only weekly entry, for anybody without an RSVP row for it, and nothing
// in the product ever wrote that row for somebody else, so a ticked badge took
// the class out of every member's calendar app. `visibility` is the one setting
// that restricts who sees a date, and that half still holds: a members-only date
// rides along only for a paid member or a manager.
//
// The GET handler is a plain function on the exported Route, so it is called
// directly, the way agent.test.ts calls the manager agent's. The fake below
// serves every table it is seeded with and evaluates the filters the route
// sends, so a date is in or out of the feed because of the row and the query,
// not because the fake answered every read with the same thing. The seed also
// holds what the old rule read (an invite-only weekly entry, and somebody
// else's reply), so a route that went back to hiding invite-only dates would
// find what it needs to do it, and fail here.
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { hashToken } from "@/lib/manager-api-tokens";

type Row = Record<string, unknown>;
type Result = { data: unknown; error: { message: string } | null };

/** 11am Monday 2 November 2026 in Sydney (AEDT, +11:00). */
const NOW = "2026-11-02T00:00:00.000Z";

const PAID_MEMBER = "b1111111-1111-4111-8111-111111111111";
const TRIAL_VISITOR = "b2222222-2222-4222-8222-222222222222";
const SOMEBODY_ELSE = "b3333333-3333-4333-8333-333333333333";
const RAW_TOKEN: Record<string, string> = {
  [PAID_MEMBER]: "feed-token-paid-member",
  [TRIAL_VISITOR]: "feed-token-trial-visitor",
};

const INVITE_ONLY_ENTRY = "c1111111-1111-4111-8111-111111111111";
const OPEN_CLASS = "d1111111-1111-4111-8111-111111111111";
const BADGED_ONE_OFF = "d2222222-2222-4222-8222-222222222222";
const DATE_OF_INVITE_ONLY_ENTRY = "d3333333-3333-4333-8333-333333333333";
const MEMBERS_ONLY = "d4444444-4444-4444-8444-444444444444";
const MEMBERS_ONLY_BADGED = "d5555555-5555-4555-8555-555555555555";

/** A date on the calendar, 6pm to 8pm Sydney time, `days` after Monday. */
const date = (id: string, days: number, over: Row = {}): Row => {
  const starts = new Date(Date.parse("2026-11-02T07:00:00.000Z") + days * 86_400_000);
  return {
    id,
    series_id: null,
    title: "Evening class",
    description: null,
    instructor_name: null,
    location: null,
    starts_at: starts.toISOString(),
    ends_at: new Date(starts.getTime() + 2 * 3_600_000).toISOString(),
    status: "scheduled",
    visibility: "public",
    invite_only: false,
    updated_at: "2026-10-20T00:00:00.000Z",
    ...over,
  };
};

async function seed(): Promise<Record<string, Row[]>> {
  return {
    calendar_feed_tokens: [
      {
        id: "tok-member",
        user_id: PAID_MEMBER,
        token_hash: await hashToken(RAW_TOKEN[PAID_MEMBER]),
        revoked_at: null,
      },
      {
        id: "tok-visitor",
        user_id: TRIAL_VISITOR,
        token_hash: await hashToken(RAW_TOKEN[TRIAL_VISITOR]),
        revoked_at: null,
      },
    ],
    calendar_series: [{ id: INVITE_ONLY_ENTRY, invite_only: true, is_active: true }],
    calendar_events: [
      date(OPEN_CLASS, 0),
      date(BADGED_ONE_OFF, 1, { title: "Grading", invite_only: true }),
      // A weekly entry's dates carry its flag when they are generated.
      date(DATE_OF_INVITE_ONLY_ENTRY, 2, {
        series_id: INVITE_ONLY_ENTRY,
        title: "Squad training",
        invite_only: true,
      }),
      date(MEMBERS_ONLY, 3, { title: "Members open mat", visibility: "members" }),
      date(MEMBERS_ONLY_BADGED, 4, {
        title: "Instructor class",
        visibility: "members",
        invite_only: true,
      }),
    ],
    // Somebody else has replied to the badged one-off. Neither subscriber has
    // replied to anything.
    event_rsvps: [{ event_id: BADGED_ONE_OFF, user_id: SOMEBODY_ELSE, response: "going" }],
  };
}

/** Who holds a paid membership. Neither subscriber is a manager. */
const PAID = new Set([PAID_MEMBER]);

/**
 * In-memory service-role client. Reads evaluate `eq`, `gte` and `lte` against
 * the seeded rows (order and limit are no-ops; the route asks for far fewer
 * than its limit). An update changes nothing, since the only one this route
 * sends is the best-effort "last used" stamp. The two RPCs answer by the user
 * id they are asked about.
 */
function fakeAdmin(tables: Record<string, Row[]>) {
  return {
    from: (table: string) => {
      const filters: ((r: Row) => boolean)[] = [];
      const result = (): Result => ({
        data: (tables[table] ?? []).filter((r) => filters.every((f) => f(r))),
        error: null,
      });
      const b = {
        select: () => b,
        update: () => b,
        eq: (col: string, val: unknown) => (filters.push((r) => r[col] === val), b),
        gte: (col: string, val: string) => (filters.push((r) => String(r[col]) >= val), b),
        lte: (col: string, val: string) => (filters.push((r) => String(r[col]) <= val), b),
        order: () => b,
        limit: () => b,
        maybeSingle: () => {
          const rows = result().data as Row[];
          return Promise.resolve({ data: rows[0] ?? null, error: null });
        },
        then: (resolve: (r: Result) => unknown, reject?: (e: unknown) => unknown) =>
          Promise.resolve().then(result).then(resolve, reject),
      };
      return b;
    },
    rpc: (name: string, args: { _user_id: string; _role?: string }) => {
      if (name === "has_active_paid_membership")
        return Promise.resolve({ data: PAID.has(args._user_id), error: null });
      if (name === "has_role" && args._role === "manager")
        return Promise.resolve({ data: false, error: null });
      throw new Error(`unexpected rpc ${name}`);
    },
  };
}

let currentAdmin: unknown;
vi.mock("@/integrations/supabase/client.server", () => ({
  get supabaseAdmin() {
    return currentAdmin;
  },
}));

type FeedHandler = (ctx: { params: { token: string } }) => Promise<Response>;

async function feedFor(userId: string): Promise<Response> {
  const { Route } = await import("./$token");
  const handlers = (Route as unknown as { options: { server: { handlers: { GET: FeedHandler } } } })
    .options.server.handlers;
  return handlers.GET({ params: { token: RAW_TOKEN[userId] } });
}

/** Each VEVENT's date id, mapped to its SUMMARY and DESCRIPTION. */
function eventsIn(ics: string): Map<string, { summary: string; description: string }> {
  // A long content line is folded onto the next with a leading space.
  const unfolded = ics.replace(/\r\n /g, "");
  const events = new Map<string, { summary: string; description: string }>();
  for (const block of unfolded.split("BEGIN:VEVENT").slice(1)) {
    const field = (name: string) =>
      block
        .split("\r\n")
        .find((l) => l.startsWith(`${name}:`))
        ?.slice(name.length + 1) ?? "";
    events.set(field("UID").split("@")[0], {
      summary: field("SUMMARY"),
      description: field("DESCRIPTION"),
    });
  }
  return events;
}

describe("personal calendar feed", () => {
  beforeEach(async () => {
    vi.resetModules();
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date(NOW));
    currentAdmin = fakeAdmin(await seed());
  });
  afterEach(() => {
    vi.useRealTimers();
    vi.restoreAllMocks();
  });

  it("hands a member every invite-only date, with its badge, though they have replied to none", async () => {
    const res = await feedFor(PAID_MEMBER);
    expect(res.status).toBe(200);
    expect(res.headers.get("content-type")).toMatch(/^text\/calendar/);
    const events = eventsIn(await res.text());

    expect([...events.keys()].sort()).toEqual(
      [
        OPEN_CLASS,
        BADGED_ONE_OFF,
        DATE_OF_INVITE_ONLY_ENTRY,
        MEMBERS_ONLY,
        MEMBERS_ONLY_BADGED,
      ].sort(),
    );
    expect(events.get(BADGED_ONE_OFF)?.summary).toBe("Grading (invite only)");
    expect(events.get(DATE_OF_INVITE_ONLY_ENTRY)?.summary).toBe("Squad training (invite only)");
    expect(events.get(MEMBERS_ONLY_BADGED)?.summary).toBe("Instructor class (invite only)");
    expect(events.get(BADGED_ONE_OFF)?.description).toContain("Invite only.");
    // The badge is the date's own: a date without it reads plainly.
    expect(events.get(OPEN_CLASS)?.summary).toBe("Evening class");
    expect(events.get(OPEN_CLASS)?.description).not.toContain("Invite only.");
  });

  it("still leaves members-only dates out for somebody without a paid membership", async () => {
    const res = await feedFor(TRIAL_VISITOR);
    expect(res.status).toBe(200);
    const events = eventsIn(await res.text());

    // The public invite-only dates are there, badged, for them too.
    expect([...events.keys()].sort()).toEqual(
      [OPEN_CLASS, BADGED_ONE_OFF, DATE_OF_INVITE_ONLY_ENTRY].sort(),
    );
    expect(events.get(BADGED_ONE_OFF)?.summary).toBe("Grading (invite only)");
    expect(events.get(DATE_OF_INVITE_ONLY_ENTRY)?.summary).toBe("Squad training (invite only)");
    expect(events.has(MEMBERS_ONLY)).toBe(false);
    expect(events.has(MEMBERS_ONLY_BADGED)).toBe(false);
  });
});
